import hashlib
import hmac
import json
import re

from payhook.errors import InvalidNotification

_WINDOW_SECONDS = 300
_TIMESTAMP_RE = re.compile(r"[+-]?[0-9]+")
_CURRENCY_RE = re.compile(r"[A-Z]{3}")
_HEX_RE = re.compile(r"[0-9a-fA-F]+")


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format.

    Current deliveries carry ``X-Pay-Signature: v1=<digest>``: HMAC-SHA256
    over the ASCII timestamp, ``.``, and the exact received body bytes. v0
    connector deliveries, whose relay reformats the body, may instead carry
    ``X-Pay-Receipt: r0=<digest>``: HMAC-SHA256 over the ASCII timestamp,
    ``.``, and the UTF-8 ``event_id`` from the JSON object. A matching
    receipt plus a timestamp inside the acceptance window is sufficient for
    that path; it adds no body fingerprint and no provider lookup.
    """
    if isinstance(raw_body, str):
        raw_body = raw_body.encode("utf-8")
    if not isinstance(raw_body, (bytes, bytearray)):
        raise InvalidNotification("body must be bytes")

    timestamp = _header(headers, "X-Pay-Timestamp")
    if timestamp is None or _TIMESTAMP_RE.fullmatch(timestamp) is None:
        raise InvalidNotification("missing or malformed X-Pay-Timestamp")
    if abs(int(timestamp) - now) > _WINDOW_SECONDS:
        raise InvalidNotification("timestamp outside acceptance window")

    event = _load_object(raw_body)
    prefix = timestamp.encode("ascii") + b"."

    if _digest_matches(headers, "X-Pay-Signature", "v1",
                       secret, prefix + bytes(raw_body)):
        return _fields(event)

    event_id = event.get("event_id")
    if isinstance(event_id, str) and _digest_matches(
            headers, "X-Pay-Receipt", "r0",
            secret, prefix + event_id.encode("utf-8")):
        return _fields(event)

    raise InvalidNotification("no matching signature or receipt")


def _header(headers, name):
    """Return the header value by case-insensitive name, or None."""
    target = name.lower()
    for key, value in headers.items():
        if not (isinstance(key, str) and key.lower() == target):
            continue
        if isinstance(value, (bytes, bytearray)):
            try:
                value = bytes(value).decode("utf-8")
            except UnicodeDecodeError:
                return None
        if not isinstance(value, str):
            return None
        return value.strip()
    return None


def _digest_matches(headers, header_name, scheme, secret, message):
    """True when <header_name> is "<scheme>=<digest>" and the digest is the
    HMAC-SHA256 of ``message`` under ``secret``."""
    value = _header(headers, header_name)
    if value is None:
        return False
    digest = value[len(scheme) + 1:] if value.startswith(scheme + "=") else None
    if digest is None or _HEX_RE.fullmatch(digest) is None:
        return False
    expected = hmac.new(secret, message, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, digest.lower())


def _load_object(raw_body):
    try:
        event = json.loads(raw_body)
    except ValueError:
        raise InvalidNotification("body is not valid JSON") from None
    if not isinstance(event, dict):
        raise InvalidNotification("body is not a JSON object")
    return event


def _fields(event):
    event_id = event.get("event_id")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("missing or malformed event_id")
    account_id = event.get("account_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("missing or malformed account_id")
    amount = event.get("amount_minor")
    if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
        raise InvalidNotification("missing or malformed amount_minor")
    currency = event.get("currency")
    if not isinstance(currency, str) or _CURRENCY_RE.fullmatch(currency) is None:
        raise InvalidNotification("missing or malformed currency")
    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount,
        "currency": currency,
    }

